-- Curated production content has no user owner and cannot be edited through user routes.
ALTER TABLE exercises ALTER COLUMN user_id DROP NOT NULL;

WITH catalog(id, name, note, body, source_title, source_url) AS (VALUES
('ca7a1000-0000-4000-8000-000000000001'::uuid, 'Жим лежа',
 'Жим штанги на горизонтальной скамье. Работают грудь, трицепс и передняя часть плеча.',
 'Упритесь стопами в пол, сведите лопатки и устойчиво расположитесь на скамье. Возьмите гриф немного шире плеч. Опускайте штангу к груди под контролем и плавно выжимайте вверх. Не используйте рывок и не усиливайте прогиб ради большего веса.',
 'NASM: Barbell Bench Press', 'https://www.nasm.org/resource-center/exercise-library/barbell-bench-press'),
('ca7a1000-0000-4000-8000-000000000002', 'Сгибание голени',
 'Сгибание ног сидя в тренажере. Акцент на заднюю поверхность бедра.',
 'Настройте сиденье и валик по росту: спина опирается на спинку, валик расположен над лодыжками. Держитесь за рукоятки и сохраняйте корпус неподвижным. Сгибайте колени плавно, затем медленно возвращайте ноги. Не бросайте груз и не помогайте движению раскачиванием.',
 'NASM: Seated Leg Curl', 'https://www.nasm.org/resource-center/exercise-library/seated-leg-curl'),
('ca7a1000-0000-4000-8000-000000000003', 'Разгибание голени',
 'Разгибание ног сидя в тренажере. Акцент на переднюю поверхность бедра.',
 'Совместите ось тренажера с коленным суставом и расположите валик на нижней части голени. Прижмите спину к спинке, держитесь за рукоятки. Плавно разгибайте колени и опускайте вес под контролем. Начните с небольшого веса, без рывков и болезненной амплитуды.',
 'Muscle & Strength: Leg Extension', 'https://www.muscleandstrength.com/exercises/leg-extension.html'),
('ca7a1000-0000-4000-8000-000000000004', 'Жим ног',
 'Жим ногами в тренажере. Работают передняя поверхность бедра и ягодицы.',
 'Устойчиво обопритесь спиной и головой на спинку, поставьте стопы на платформу примерно на ширине таза. Держитесь за рукоятки. Плавно выжимайте платформу, не запирая колени, затем контролируемо сгибайте ноги. Сохраняйте контакт со спинкой и не бросайте платформу вниз.',
 'NASM: Leg Press', 'https://www.nasm.org/resource-center/exercise-library/leg-press'),
('ca7a1000-0000-4000-8000-000000000005', 'Грудь бабочка',
 'Сведение рук в тренажере «бабочка» с опорой предплечьями. Акцент на грудные мышцы.',
 'Настройте сиденье так, чтобы локти находились на уровне груди. Упритесь стопами в пол и держите спину на спинке. Плавно сводите рычаги перед собой и медленно возвращайте их. Не уводите руки слишком далеко назад и не растягивайте плечи через дискомфорт.',
 'Muscle & Strength: Pec Dec', 'https://www.muscleandstrength.com/exercises/pec-dec.html'),
('ca7a1000-0000-4000-8000-000000000006', 'Жим стоя на плечи',
 'Строгий жим штанги стоя перед головой. Работают плечи и трицепс; корпус удерживает положение.',
 'Возьмите гриф на ширине плеч или немного шире и начните от верхней части груди. Напрягите живот и ягодицы, сохраняйте нейтральное положение спины. Выжимайте штангу над головой без толчка ногами и чрезмерного отклонения назад. Медленно верните гриф к груди.',
 'Muscle & Strength: Military Press', 'https://www.muscleandstrength.com/exercises/military-press.html'),
('ca7a1000-0000-4000-8000-000000000007', 'Верхний блок тяга',
 'Тяга верхнего блока перед собой к верхней части груди. Акцент на мышцы спины.',
 'Возьмите рукоять хватом немного шире плеч. Удерживайте корпус собранным, а спину в нейтральном положении. Тяните рукоять к ключицам, направляя лопатки вниз и назад. Плавно верните руки в исходное положение, сохраняя контроль над весом.',
 'Catalyst Athletics: Lat Pulldown', 'https://www.catalystathletics.com/exercise/725/Lat-Pulldown/'),
('ca7a1000-0000-4000-8000-000000000008', 'Горизонтальный блок тяга',
 'Тяга нижнего блока сидя с узкой нейтральной рукоятью. Акцент на спину.',
 'Сядьте устойчиво, слегка согните колени и сохраняйте нейтральное положение спины. Потяните рукоять к животу, удерживая корпус неподвижным. Медленно отпустите рукоять вперед. Не превращайте повторение в раскачивание вперед и назад.',
 'Muscle & Strength: Seated Row', 'https://www.muscleandstrength.com/exercises/seated-row.html'),
('ca7a1000-0000-4000-8000-000000000009', 'Тяга к подбородку на плечи',
 'Вертикальная тяга штанги. Работают плечи и трапеции. Название не означает, что гриф обязательно нужно доводить до подбородка.',
 'Возьмите гриф прямым хватом примерно на ширине плеч. Поднимайте его близко к корпусу, ведя движение локтями, примерно до уровня груди. Держите живот напряженным и опускайте гриф плавно. Не тяните рывком и не продолжайте движение через боль в плечах.',
 'Muscle & Strength: Barbell Upright Row', 'https://www.muscleandstrength.com/exercises/upright-row.html'),
('ca7a1000-0000-4000-8000-000000000010', 'Шраги',
 'Шраги стоя с гантелями по бокам. Акцент на трапециевидные мышцы.',
 'Встаньте ровно с гантелями по бокам, ладони направлены к телу. Поднимайте плечи, ненадолго задержитесь вверху и медленно опустите вес. Сохраняйте нейтральное положение спины. Избегайте рывков и выдвижения головы вперед.',
 'Muscle & Strength: Dumbbell Shrug', 'https://www.muscleandstrength.com/exercises/dumbbell-shrugs.html'),
('ca7a1000-0000-4000-8000-000000000011', 'Трицепс в кроссовере',
 'Разгибание рук на верхнем блоке с прямой рукоятью. Акцент на трицепс.',
 'Закрепите рукоять на верхнем блоке, возьмитесь прямым хватом и слегка наклонитесь от тазобедренных суставов. Разгибайте локти, опуская рукоять вниз. Удерживайте плечевую часть руки устойчивой, не выводите локти вперед. Медленно верните рукоять, не заваливая плечи вперед.',
 'Muscle & Strength: Straight Bar Tricep Extension', 'https://www.muscleandstrength.com/exercises/tricep-extension.html'),
('ca7a1000-0000-4000-8000-000000000012', 'Французский жим',
 'Французский жим лежа с EZ-грифом. Акцент на трицепс.',
 'Лягте на скамью и поднимите EZ-гриф над грудью. Сгибая локти, медленно опускайте гриф к области над лбом, затем разгибайте руки под контролем. Удерживайте живот напряженным, не усиливайте прогиб поясницы. Не бросайте вес к голове и не выполняйте повторения через боль в локтях.',
 'Muscle & Strength: EZ Bar Skullcrusher', 'https://www.muscleandstrength.com/exercises/ez-bar-skullcrusher.html'),
('ca7a1000-0000-4000-8000-000000000013', 'Икры в тренажере',
 'Подъем на носки стоя в тренажере с плечевыми упорами. Акцент на икроножные мышцы.',
 'Настройте плечевые упоры и поставьте переднюю часть стоп на платформу, оставив пятки свободными. Плавно опустите пятки в комфортную амплитуду, затем поднимитесь на носки. Удерживайте колени в устойчивом положении. Не пружиньте и не отбивайте вес внизу.',
 'Muscle & Strength: Standing Machine Calf Raise', 'https://www.muscleandstrength.com/exercises/standing-machine-calf-raise'),
('ca7a1000-0000-4000-8000-000000000014', 'Грудь в тренажере',
 'Жим от груди сидя в тренажере. Работают грудные мышцы, трицепс и передняя часть плеча.',
 'Настройте сиденье так, чтобы рукоятки находились на уровне середины груди. Прижмите спину к спинке и поставьте стопы на пол. Плавно выжимайте рукоятки вперед, не запирая локти, затем контролируемо верните их. Избегайте рывков и чрезмерного разведения локтей.',
 'NASM: Chest Press Machine', 'https://www.nasm.org/resource-center/exercise-library/chest-press-machine'),
('ca7a1000-0000-4000-8000-000000000015', 'Жим на наклонной скамье',
 'Жим штанги на наклонной скамье головой вверх. Акцент на верхнюю часть груди.',
 'Устойчиво поставьте стопы на пол и зафиксируйте лопатки на скамье. Обхватите гриф большим пальцем, держите его над запястьями. Плавно опускайте штангу к верхней части груди и выжимайте вверх без отбива. Для тяжелых подходов используйте страховку.',
 'Muscle & Strength: Incline Bench Press', 'https://www.muscleandstrength.com/exercises/incline-bench-press.html'),
('ca7a1000-0000-4000-8000-000000000016', 'Присед',
 'Приседание со штангой на спине. Работают бедра, ягодицы и мышцы корпуса.',
 'Расположите гриф на мышцах верхней части спины, не на шее. Снимите штангу со стоек и устойчиво поставьте стопы примерно на ширине плеч. Напрягите корпус, опускайтесь плавно и поднимайтесь без рывка. Сохраняйте положение спины и сначала освойте движение с легким весом.',
 'Muscle & Strength: Barbell Back Squat', 'https://www.muscleandstrength.com/exercises/squat.html'),
('ca7a1000-0000-4000-8000-000000000017', 'Становая тяга',
 'Классическая становая тяга штанги с пола. Работают ноги, ягодицы и мышцы спины.',
 'Поставьте стопы примерно на ширине таза, гриф над серединой стоп. Напрягите корпус и уберите слабину перед подъемом. Поднимайте штангу плавно, разгибая колени и таз, удерживая гриф близко к телу и спину нейтральной. Верните вес на пол под контролем.',
 'NASM: Barbell Deadlift', 'https://www.nasm.org/resource-center/exercise-library/barbell-deadlift'),
('ca7a1000-0000-4000-8000-000000000018', 'Болгарские выпады',
 'Сплит-присед с задней стопой на скамье и гантелями по бокам. Выполняйте подход для каждой ноги.',
 'Поставьте заднюю стопу на невысокую устойчивую опору, переднюю на пол. Держите гантели по бокам и сохраняйте нейтральное положение поясницы. Плавно опускайтесь, сгибая переднюю ногу, затем поднимайтесь через ее стопу. Подберите расстояние до опоры, при котором сохраняете равновесие.',
 'Muscle & Strength: Dumbbell Bulgarian Split Squat', 'https://www.muscleandstrength.com/exercises/one-leg-dumbbell-squat-aka-bulgarian-squat.html'),
('ca7a1000-0000-4000-8000-000000000019', 'Румынская тяга',
 'Румынская тяга со штангой из положения стоя. Акцент на заднюю поверхность бедра и ягодицы.',
 'Держите стопы примерно на ширине таза, колени слегка согнуты. Отводите таз назад, опуская штангу близко к ногам и сохраняя нейтральную спину. Остановитесь, когда почувствуете натяжение задней поверхности бедра без потери положения спины. Вернитесь вверх, разгибая таз.',
 'NASM: Romanian Deadlift (Barbell)', 'https://www.nasm.org/resource-center/exercise-library/romanian-deadlift-barbell'),
('ca7a1000-0000-4000-8000-000000000020', 'Бицепс молот',
 'Сгибание рук с гантелями нейтральным хватом. Работают сгибатели локтя и предплечья.',
 'Встаньте устойчиво с гантелями по бокам, ладони направлены друг к другу. Сгибайте локти, сохраняя нейтральный хват и устойчивое положение плеч. Плавно опускайте гантели в исходное положение. Не подбрасывайте вес раскачиванием корпуса.',
 'NASM: Dumbbell Hammer Curl', 'https://www.youtube.com/watch?v=CFBZ4jN1CMI'),
('ca7a1000-0000-4000-8000-000000000021', 'Бицепс ez гриф',
 'Сгибание рук стоя с EZ-грифом хватом снизу. Акцент на бицепс.',
 'Возьмите EZ-гриф хватом снизу примерно на ширине плеч. Удерживайте локти у корпуса и поднимайте гриф, сгибая только предплечья. Ненадолго задержитесь вверху и медленно опустите вес. Не раскачивайтесь и не выводите плечи вперед ради подъема.',
 'Weight Training Guide: EZ Bar Curl', 'https://weighttraining.guide/exercises/ez-bar-curl/'),
('ca7a1000-0000-4000-8000-000000000022', 'Тяга гантель поочередно с упором на скамью',
 'Тяга одной гантели с опорой рукой и коленом на скамью. Выполняйте подход для каждой стороны.',
 'Обопритесь рукой и коленом о скамью, другую стопу поставьте на пол. Держите спину нейтральной, корпус почти горизонтальным. Подтягивайте гантель к боку, ведя локоть близко к корпусу и не вращая туловище. Плавно опустите гантель и затем смените сторону.',
 'Bodybuilding.com: One Arm Dumbbell Row', 'https://www.youtube.com/watch?v=PgpQ4-jHiq4')
), inserted AS (
 INSERT INTO exercises(id, user_id, name, normalized_name, note)
 SELECT id, NULL, name, lower(name), note FROM catalog RETURNING id
)
INSERT INTO technique_guides(exercise_id, body, source_title, source_url, reviewed_at, source_accessed_at)
SELECT c.id, c.body, c.source_title, c.source_url, '2026-10-10T16:53:33Z', '2026-10-10T16:53:33Z'
FROM catalog c JOIN inserted i ON i.id = c.id;
